{
  "arguments": [
    {
      "claim": "The commander exercised effective command and control over MLC troops, satisfying the jurisdictional prerequisite of Article 28(a) of the Rome Statute.",
      "reasoning": "Article 28(a) applies only to a military commander or a person effectively acting as such who has effective command and control over the forces. The Trial Chamber’s finding that the commander acted as a military commander with effective control establishes that the factual prerequisite of the provision is met, thereby triggering command responsibility.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces, where:"
        }
      ]
    },
    {
      "claim": "The commander either knew or, given the circumstances, should have known that his troops were committing murder, rape and pillaging.",
      "reasoning": "Article 28(a)(i) requires that the commander have actual knowledge or constructive knowledge of the crimes. The record shows that consistent information about the crimes was brought to his attention, that he initiated inquiries, and that other MLC commanders exercised disciplinary authority in the field, indicating that a reasonable commander in his position would have been aware of the ongoing violations.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(i)",
          "quoted_text": "That military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes;"
        }
      ]
    },
    {
      "claim": "The commander failed to take all necessary and reasonable measures within his power to prevent or repress the crimes or to refer them to competent authorities.",
      "reasoning": "Article 28(a)(ii) obliges a commander to take all necessary and reasonable measures to prevent or repress the commission of crimes or to submit the matter to competent authorities. Although the commander took some measures, the Tribunal found that crimes continued throughout the operation and that the measures were insufficient given his effective control, satisfying the element of failure to act.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(ii)",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        }
      ]
    },
    {
      "claim": "Logistical difficulties, limited investigative power, and cooperation with Central African Republic authorities do not excuse the commander’s failure, because customary international humanitarian law imposes liability when superiors have information and do not take feasible measures to prevent or repress breaches.",
      "reasoning": "Article 86(2) of Additional Protocol I mirrors the Rome Statute’s command‑responsibility requirement, stating that superiors are not absolved if they had information that should have led them to conclude a breach was occurring and they did not take all feasible measures to prevent or repress it. The commander’s knowledge of the crimes and his continued in‑action despite cooperation efforts satisfy the customary standard, reinforcing that the failure to act was unlawful.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "The fact that a breach of the Conventions or of this Protocol was committed by a subordinate does not absolve his superiors from penal or disciplinary responsibility, as the case may be, if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach and if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    }
  ]
}

{
  "objections": [
    {
      "target_argument_id": "arg_f3070f66",
      "ground": "The argument conflates the treaty standard of 'necessary and reasonable measures' with the customary standard of 'all feasible measures,' which are distinct legal tests.",
      "reasoning": "Article 28(a)(ii) of the Rome Statute requires 'all necessary and reasonable measures within his or her power.' Article 86(2) of Additional Protocol I requires 'all feasible measures.' These are not synonymous; 'necessary and reasonable' is a different threshold from 'feasible.' Citing AP I to prove a failure under the Rome Statute is a legal error of mis-citation and mis-application of the standard.",
      "severity": "material",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(ii)"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)"
        }
      ]
    }
  ]
}

