{
  "arguments": [
    {
      "claim": "The commander exercised effective command and control over MLC troops, satisfying the factual prerequisite of Article 28(a) of the Rome Statute.",
      "reasoning": "Article 28(a) imposes command responsibility only where the individual is a military commander or is effectively acting as such and has effective command and control over the forces. The Trial Chamber expressly found that the commander acted as a military commander with effective control over the MLC troops, which meets this prerequisite and triggers the applicability of the provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces, where:"
        }
      ]
    },
    {
      "claim": "Given the consistent information brought to his attention and the disciplinary actions taken by other MLC commanders, the commander had actual or constructive knowledge of the crimes, satisfying element (i) of Article 28(a).",
      "reasoning": "Element (i) requires that the commander either knew or, owing to the circumstances, should have known that his forces were committing or about to commit the crimes. The record shows that consistent information about murders, rapes and pillaging was repeatedly presented to him and that other MLC commanders were exercising disciplinary authority in the field. Under the constructive‑knowledge standard, a commander in such circumstances is deemed to have knowledge. The same principle is reflected in customary law, which holds superiors responsible when they had information that should have led them to conclude a breach was occurring.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(i)",
          "quoted_text": "That military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes;"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach"
        }
      ]
    },
    {
      "claim": "The commander failed to take all necessary and reasonable measures within his power to prevent or repress the crimes or to refer them to competent authorities, satisfying element (ii) of Article 28(a).",
      "reasoning": "Element (ii) obliges a commander to take all necessary and reasonable measures within his power to prevent or repress the commission of crimes or to submit the matter to competent authorities. The commander only sent letters and requested that the Central African Republic investigate, while the crimes continued unabated. He possessed the authority to discipline troops directly—evidenced by other MLC commanders exercising disciplinary authority—so he could have taken stronger, reasonable measures (e.g., ordering arrests, imposing strict rules of engagement). The Trial Chamber’s finding that his measures were insufficient is part of the factual record and confirms the failure to meet the statutory standard.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(ii)",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        }
      ]
    },
    {
      "claim": "The distinction between the Rome Statute’s “necessary and reasonable” standard and the Additional Protocol I’s “feasible” standard does not undermine liability; the evidence satisfies the higher Rome Statute threshold and the customary standard reinforces the conclusion.",
      "reasoning": "While Article 86(2) of Additional Protocol I speaks of “all feasible measures,” Article 28(a)(ii) of the Rome Statute requires “all necessary and reasonable measures,” which is at least as demanding. The commander’s limited actions fall short of both standards. Citing the customary provision is therefore permissible to illustrate the parallel duty, but the core liability rests on the Rome Statute’s own wording, which the factual record already meets.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)(ii)",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    }
  ]
}

